        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Il buio oltre internet. Dall’Iran a Mosca, gli shutdown del 2025",
        "testo_it": "Report di Access Now denuncia l'aumento degli shutdown di internet in Iran e Russia nel 2025.",
        "priorita": "Media",
        "id_gruppo": 20,
        "link": "https://ilmanifesto.it/l-buio-oltre-internet-dalliran-a-mosca-gli-shutdown-del-2025",
        "orario": "00:07 - 1 Aprile",
